'AC-audit.trace-projection.1'; from __future__ import annotations; from decimal import Decimal; import pytest; from src.audit import TraceConfidenceProjection, TraceLineage, TraceRecord, TraceRecordValidationError, TraceResult; from .conftest import authority, decision_policy, observation
def test_AC_audit_trace_projection_1_uses_fixed_machine_cohort_heads():
    passed = observation(target_id='machine-a'); failed = observation(scope=passed.scope, target_id='machine-b', result=TraceResult.FAIL, score='0'); manual = observation(scope=passed.scope, target_id='manual-extra', profile=authority(tier='CODE-ONLY', proof_kind='exact', provenance='deterministic')); correction = observation(scope=passed.scope, target_id='machine-b', target_version='v2', assertion_version='v2', supersedes_id=failed.record_id); projection = TraceConfidenceProjection(cohort_id='machine-extraction', cohort_version='v1', members=(passed.lineage, failed.lineage)); confidence = projection.evaluate([passed, failed, manual, correction]); assert confidence.value == Decimal('1'); _m1_first = observation(target_id='shared-target', assertion_id='parser-shape'); _m1_second = observation(scope=_m1_first.scope, target_id='shared-target', assertion_id='balance-invariant', result=TraceResult.FAIL, score='0'); _m1_projection = TraceConfidenceProjection(cohort_id='two-independent-assertions', cohort_version='v1', members=(TraceLineage.from_refs(_m1_first.target, _m1_first.assertion), TraceLineage.from_refs(_m1_second.target, _m1_second.assertion))); assert _m1_projection.evaluate([_m1_first, _m1_second]).value == Decimal('0.5'); _m2_parent = observation(); _m2_decision = TraceRecord.decision(scope=_m2_parent.scope, target=_m2_parent.target, policy=decision_policy(assertion_id='terminal-confidence'), execution_id=_m2_parent.execution_id, occurred_at=_m2_parent.occurred_at, parents=[_m2_parent]); _m2_projection = TraceConfidenceProjection(cohort_id='terminal-decisions', cohort_version='v1', members=(_m2_decision.lineage,)); assert _m2_projection.evaluate([_m2_parent, _m2_decision]).value == Decimal('1'); _m2_correction = observation(scope=_m2_parent.scope, target_version='v2', assertion_version='v2', supersedes_id=_m2_parent.record_id)
    with pytest.raises(TraceRecordValidationError, match='missing'): _m2_projection.evaluate([_m2_parent, _m2_decision, _m2_correction])
